// =====================================================
// SOLUCIONES COLINA — Pantalla de Onboarding / Registro
// Primera vez que el usuario abre la app
// =====================================================
import React, { useState } from 'react'
import { registrarUsuario, type RegistroData } from '../services/authService'
import { GoldenParticlesLogo } from '../components/GoldenParticlesLogo'

interface RegistroScreenProps {
  onRegistrado: (sal: string, pin: string) => void
  onIrALogin: () => void
}

type Paso = 'empresa' | 'pin' | 'confirmacion'

export const RegistroScreen: React.FC<RegistroScreenProps> = ({ onRegistrado, onIrALogin }) => {
  const [paso, setPaso] = useState<Paso>('empresa')
  const [cargando, setCargando] = useState(false)
  const [error, setError] = useState('')

  // Datos empresa
  const [nombre, setNombre] = useState('')
  const [nit, setNit] = useState('')
  const [dv, setDv] = useState('')
  const [correo, setCorreo] = useState('')
  const [telefono, setTelefono] = useState('')
  const [ciudad, setCiudad] = useState('')

  // PIN
  const [pin, setPin] = useState('')
  const [pinConfirm, setPinConfirm] = useState('')

  const soloNumeros = (val: string, setter: (v: string) => void, max: number) => {
    const limpio = val.replace(/\D/g, '').slice(0, max)
    setter(limpio)
  }

  const validarEmpresa = () => {
    if (!nombre.trim()) return 'El nombre de la empresa es obligatorio'
    if (!nit.trim() || nit.length < 7) return 'NIT inválido (mínimo 7 dígitos)'
    if (!dv.trim()) return 'El dígito de verificación es obligatorio'
    if (!correo.includes('@')) return 'Correo electrónico inválido'
    return ''
  }

  const validarPin = () => {
    if (pin.length !== 6) return 'El PIN debe tener exactamente 6 dígitos'
    if (pin !== pinConfirm) return 'Los PINs no coinciden'
    return ''
  }

  const avanzarEmpresa = () => {
    const err = validarEmpresa()
    if (err) { setError(err); return }
    setError('')
    setPaso('pin')
  }

  const avanzarPin = () => {
    const err = validarPin()
    if (err) { setError(err); return }
    setError('')
    setPaso('confirmacion')
  }

  const confirmarRegistro = async () => {
    setCargando(true)
    setError('')
    try {
      const datos: RegistroData = { nombre, nit, dv, correo, pin, telefono, ciudad }
      const sal = await registrarUsuario(datos)
      onRegistrado(sal, datos.pin)
    } catch (e) {
      setError('Error al guardar los datos. Intenta de nuevo.')
    } finally {
      setCargando(false)
    }
  }

  return (
    <div className="auth-root">
      <div className="auth-card">
        <GoldenParticlesLogo size={68} mostrarAura={true} />
        <h1 className="auth-titulo font-serif">Crear cuenta</h1>
        <p className="auth-sub">
          {paso === 'empresa' && 'Datos de tu empresa'}
          {paso === 'pin' && 'Crea tu PIN de acceso'}
          {paso === 'confirmacion' && 'Confirma tu información'}
        </p>

        {/* Selector de modo: Iniciar sesión o Crear cuenta */}
        <div className="auth-switcher">
          <button
            type="button"
            className="auth-switch-btn"
            onClick={onIrALogin}
          >
            Iniciar sesión
          </button>
          <button
            type="button"
            className="auth-switch-btn activo"
          >
            Crear cuenta
          </button>
        </div>

        {/* Indicador de pasos */}
        <div className="pasos-indicador">
          {(['empresa', 'pin', 'confirmacion'] as Paso[]).map((p, i) => (
            <div key={p} className={`paso-dot ${paso === p ? 'activo' : ''} ${['pin', 'confirmacion'].indexOf(paso) > i - 1 || paso === 'confirmacion' ? 'completado' : ''}`} />
          ))}
        </div>

        {/* Error */}
        {error && <div className="auth-error">{error}</div>}

        {/* Paso 1: Empresa en Grid de 2 Columnas para escritorio */}
        {paso === 'empresa' && (
          <div className="auth-form auth-form-grid">
            <div className="campo-grupo campo-span-2">
              <label className="campo-label">Nombre / Razón Social *</label>
              <input
                className="campo-input"
                type="text"
                placeholder="Ej: La Gran Colina Arquitectos"
                value={nombre}
                onChange={e => setNombre(e.target.value)}
                autoComplete="organization"
              />
            </div>

            <div className="campo-grupo">
              <label className="campo-label">NIT *</label>
              <div className="campo-nit-dv-row">
                <input
                  className="campo-input campo-flex"
                  type="text"
                  inputMode="numeric"
                  placeholder="100120471"
                  value={nit}
                  onChange={e => soloNumeros(e.target.value, setNit, 12)}
                />
                <span className="campo-guion">-</span>
                <input
                  className="campo-input campo-dv"
                  type="text"
                  inputMode="numeric"
                  placeholder="4"
                  value={dv}
                  onChange={e => soloNumeros(e.target.value, setDv, 1)}
                />
              </div>
            </div>

            <div className="campo-grupo">
              <label className="campo-label">Correo electrónico *</label>
              <input
                className="campo-input"
                type="email"
                placeholder="empresa@correo.com"
                value={correo}
                onChange={e => setCorreo(e.target.value)}
                autoComplete="email"
              />
            </div>

            <div className="campo-grupo">
              <label className="campo-label">Teléfono (opcional)</label>
              <input
                className="campo-input"
                type="tel"
                placeholder="300 123 4567"
                value={telefono}
                onChange={e => setTelefono(e.target.value)}
              />
            </div>

            <div className="campo-grupo">
              <label className="campo-label">Ciudad (opcional)</label>
              <input
                className="campo-input"
                type="text"
                placeholder="Bogotá D.C., Medellín..."
                value={ciudad}
                onChange={e => setCiudad(e.target.value)}
              />
            </div>

            <div className="campo-grupo campo-span-2">
              <button className="btn-auth-primario" onClick={avanzarEmpresa}>
                Continuar →
              </button>
            </div>
          </div>
        )}

        {/* Paso 2: PIN */}
        {paso === 'pin' && (
          <div className="auth-form">
            <p className="pin-descripcion">
              Tu PIN cifra todos los datos en tu dispositivo. <strong>No lo compartas.</strong>
            </p>
            <div className="campo-grupo">
              <label className="campo-label">PIN de 6 dígitos *</label>
              <input
                className="campo-input pin-input"
                type="password"
                inputMode="numeric"
                maxLength={6}
                placeholder="••••••"
                value={pin}
                onChange={e => soloNumeros(e.target.value, setPin, 6)}
              />
            </div>
            <div className="campo-grupo">
              <label className="campo-label">Confirmar PIN *</label>
              <input
                className="campo-input pin-input"
                type="password"
                inputMode="numeric"
                maxLength={6}
                placeholder="••••••"
                value={pinConfirm}
                onChange={e => soloNumeros(e.target.value, setPinConfirm, 6)}
              />
            </div>
            <div className="auth-btn-row">
              <button className="btn-auth-secundario" onClick={() => { setError(''); setPaso('empresa') }}>
                ← Atrás
              </button>
              <button className="btn-auth-primario" onClick={avanzarPin}>
                Continuar →
              </button>
            </div>
          </div>
        )}

        {/* Paso 3: Confirmación */}
        {paso === 'confirmacion' && (
          <div className="auth-form">
            <div className="confirmacion-resumen confirmacion-grid">
              <div className="confirmacion-row">
                <span className="confirmacion-label">Empresa</span>
                <span className="confirmacion-valor">{nombre}</span>
              </div>
              <div className="confirmacion-row">
                <span className="confirmacion-label">NIT</span>
                <span className="confirmacion-valor">{nit}-{dv}</span>
              </div>
              <div className="confirmacion-row">
                <span className="confirmacion-label">Correo</span>
                <span className="confirmacion-valor">{correo}</span>
              </div>
              {ciudad && (
                <div className="confirmacion-row">
                  <span className="confirmacion-label">Ciudad</span>
                  <span className="confirmacion-valor">{ciudad}</span>
                </div>
              )}
              <div className="confirmacion-row">
                <span className="confirmacion-label">PIN</span>
                <span className="confirmacion-valor">••••••</span>
              </div>
            </div>
            <div className="aviso-privacidad">
              🔒 Gestión segura de facturas electrónicas para tu empresa por <strong>Colina Studio</strong>.
            </div>
            <div className="auth-btn-row">
              <button className="btn-auth-secundario" onClick={() => { setError(''); setPaso('pin') }}>
                ← Atrás
              </button>
              <button className="btn-auth-primario" onClick={confirmarRegistro} disabled={cargando}>
                {cargando ? 'Guardando...' : '✓ Crear cuenta'}
              </button>
            </div>
          </div>
        )}

        {/* Enlace inferior para iniciar sesión */}
        <div className="auth-footer-switch">
          <span>¿Ya tienes una cuenta registrada?</span>
          <button
            type="button"
            className="auth-link-btn"
            onClick={onIrALogin}
          >
            Iniciar sesión con tu PIN →
          </button>
        </div>
      </div>
    </div>
  )
}
