import React from 'react'

interface ReceiptBarcodeProps {
  valor: string
}

export const ReceiptBarcode: React.FC<ReceiptBarcodeProps> = ({ valor }) => {
  // Patrón de líneas verticales (anchos: 1px, 2px, 3px, espaciados: 1px, 2px)
  const barras = [
    2, 1, 3, 2, 1, 2, 1, 3, 1, 2, 2, 1, 3, 1, 1, 2, 3, 2, 1, 1, 2, 1, 3, 2, 1,
    2, 1, 1, 3, 2, 1, 2, 1, 3, 2, 1, 1, 2, 3, 1, 2, 1, 3, 2, 1, 2, 1, 1, 3, 2
  ]

  return (
    <div className="receipt-barcode-box">
      <div className="receipt-barcode-lines" aria-hidden="true">
        {barras.map((w, idx) => (
          <span
            key={idx}
            className="receipt-bar"
            style={{ width: `${w * 1.5}px` }}
          />
        ))}
      </div>
      <span className="receipt-barcode-text font-mono">{valor}</span>
    </div>
  )
}
