// =====================================================
// COLINA STUDIO — Utilidad de Fechas Oficiales (DIAN)
// Zona horaria obligatoria: America/Bogota (UTC-05:00)
// =====================================================

export const ZONA_HORARIA_BOGOTA = 'America/Bogota'
export const OFFSET_BOGOTA_MINUTOS = -5 * 60 // -300 minutos

/**
 * Obtiene las partes de la fecha en la zona horaria America/Bogota
 * a partir de cualquier Date o timestamp UTC.
 */
export function obtenerPartesFechaBogota(fecha: Date = new Date()): {
  año: number
  mes: number // 1-12
  dia: number // 1-31
  hora: number // 0-23
  minuto: number // 0-59
  segundo: number // 0-59
  cadenaFecha: string // YYYY-MM-DD
  cadenaHora: string // HH:mm:ss
  cadenaISO: string // YYYY-MM-DDTHH:mm:ss-05:00
} {
  const formateador = new Intl.DateTimeFormat('en-CA', {
    timeZone: ZONA_HORARIA_BOGOTA,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  })

  const partes = formateador.formatToParts(fecha)
  const valores: Record<string, string> = {}
  for (const p of partes) {
    valores[p.type] = p.value
  }

  const año = parseInt(valores.year, 10)
  const mes = parseInt(valores.month, 10)
  const dia = parseInt(valores.day, 10)
  let hora = parseInt(valores.hour, 10)
  if (hora === 24) hora = 0
  const minuto = parseInt(valores.minute, 10)
  const segundo = parseInt(valores.second, 10)

  const pad = (n: number) => n.toString().padStart(2, '0')
  const cadenaFecha = `${año}-${pad(mes)}-${pad(dia)}`
  const cadenaHora = `${pad(hora)}:${pad(minuto)}:${pad(segundo)}`
  const cadenaISO = `${cadenaFecha}T${cadenaHora}-05:00`

  return { año, mes, dia, hora, minuto, segundo, cadenaFecha, cadenaHora, cadenaISO }
}

/**
 * Retorna la fecha actual de Bogotá en formato YYYY-MM-DD (para inputs date de HTML).
 * IMPORTANTE: Nunca usar new Date().toISOString().slice(0,10) porque da UTC y después
 * de las 19:00 hora Colombia ya es el día siguiente en UTC.
 */
export function hoyBogota(): string {
  return obtenerPartesFechaBogota().cadenaFecha
}

/**
 * Retorna fecha y hora actual en formato ISO 8601 con offset colombiano (-05:00).
 */
export function ahoraBogotaISO(): string {
  return obtenerPartesFechaBogota().cadenaISO
}

/**
 * Formatea una fecha ISO para visualización colombiana (ej. 07/11/2026 21:31).
 */
export function formatearFechaBogotaCorta(isoStr: string): string {
  if (!isoStr) return ''
  try {
    const d = new Date(isoStr)
    const partes = obtenerPartesFechaBogota(d)
    const pad = (n: number) => n.toString().padStart(2, '0')
    return `${pad(partes.dia)}/${pad(partes.mes)}/${partes.año} ${pad(partes.hora)}:${pad(partes.minuto)}`
  } catch {
    return isoStr
  }
}

/**
 * Formatea para encabezados del mes (ej. NOVIEMBRE 2026).
 */
export function formatearMesAñoBogota(fecha: Date = new Date()): string {
  const meses = [
    'ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO',
    'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'
  ]
  const partes = obtenerPartesFechaBogota(fecha)
  return `${meses[partes.mes - 1]} ${partes.año}`
}
