// Hook useNavegacion para sincronizar componentes con el stack
// =====================================================
import { useState, useEffect, useCallback } from 'react'
import {
  navegador,
  type EstadoNavegacion,
  type PantallaId,
  type TabId
} from '../services/navigationService'

export function useNavegacion() {
  const [estado, setEstado] = useState<EstadoNavegacion>(navegador.obtenerEstado())

  useEffect(() => {
    const desuscribir = navegador.suscribir(nuevoEstado => {
      setEstado(nuevoEstado)
    })
    return desuscribir
  }, [])

  const cima = estado.pila[estado.pila.length - 1]
  const pantallaActual = cima ? cima.pantalla : 'inicio'
  const paramsActuales = cima?.params

  const abrir = useCallback((pantalla: PantallaId, params?: Record<string, any>) => navegador.abrir(pantalla, params), [])
  const cambiarTab = useCallback((tab: TabId) => navegador.cambiarTab(tab), [])
  const reemplazar = useCallback((pantalla: PantallaId, params?: Record<string, any>) => navegador.reemplazar(pantalla, params), [])
  const reiniciar = useCallback((pantalla: PantallaId, params?: Record<string, any>) => navegador.reiniciar(pantalla, params), [])
  const volver = useCallback(() => navegador.retroceder(), [])
  const setFormularioModificado = useCallback((mod: boolean) => navegador.setFormularioModificado(mod), [])
  const setModalActivo = useCallback((modal: string | null) => navegador.setModalActivo(modal), [])
  const mostrarToast = useCallback((mensaje: string, duracionMs?: number) => navegador.mostrarToast(mensaje, duracionMs), [])

  return {
    estado,
    pila: estado.pila,
    pantallaActual,
    params: paramsActuales,
    tabActivo: estado.tabActivo,
    modalActivo: estado.modalActivo,
    formularioModificado: estado.formularioModificado,
    mensajeToast: estado.mensajeToast,

    abrir,
    cambiarTab,
    reemplazar,
    reiniciar,
    volver,
    setFormularioModificado,
    setModalActivo,
    mostrarToast
  }
}
