// =====================================================
// SOLUCIONES COLINA — Servicio de Cifrado AES-256-GCM
// Usa Web Crypto API nativa del navegador/Capacitor
// Los datos NUNCA salen del dispositivo sin cifrar
// =====================================================

const ALGORITHM = 'AES-GCM'
const KEY_LENGTH = 256
const IV_LENGTH = 12  // 96 bits para AES-GCM

/** Convierte un Uint8Array a ArrayBuffer concreto (compatible con Web Crypto) */
function toBuffer(arr: Uint8Array): ArrayBuffer {
  return arr.buffer.slice(arr.byteOffset, arr.byteOffset + arr.byteLength) as ArrayBuffer
}

/**
 * Deriva una clave AES-256 a partir de un PIN y una sal única del dispositivo.
 * Usa PBKDF2 con 200.000 iteraciones (OWASP 2024).
 */
async function derivarClave(pin: string, sal: Uint8Array): Promise<CryptoKey> {
  const enc = new TextEncoder()
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    toBuffer(enc.encode(pin)),
    'PBKDF2',
    false,
    ['deriveBits', 'deriveKey']
  )
  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: toBuffer(sal),
      iterations: 200_000,
      hash: 'SHA-256'
    },
    keyMaterial,
    { name: ALGORITHM, length: KEY_LENGTH },
    false,
    ['encrypt', 'decrypt']
  )
}

/**
 * Genera un hash SHA-256 de un PIN con sal.
 */
export async function hashPin(pin: string, sal: string): Promise<string> {
  const enc = new TextEncoder()
  const data = enc.encode(pin + sal)
  const hashBuffer = await crypto.subtle.digest('SHA-256', toBuffer(data))
  return Array.from(new Uint8Array(hashBuffer))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
}

/**
 * Genera una sal aleatoria (base64).
 */
export function generarSal(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(32))
  return btoa(String.fromCharCode(...bytes))
}

/**
 * Cifra un objeto JSON con AES-256-GCM.
 * Retorna: "base64(iv):base64(ciphertext)"
 */
export async function cifrar(datos: unknown, pin: string, salBase64: string): Promise<string> {
  const sal = Uint8Array.from(atob(salBase64), c => c.charCodeAt(0))
  const clave = await derivarClave(pin, sal)
  const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH))
  const enc = new TextEncoder()
  const plaintext = enc.encode(JSON.stringify(datos))

  const cipherBuffer = await crypto.subtle.encrypt(
    { name: ALGORITHM, iv: toBuffer(iv) },
    clave,
    toBuffer(plaintext)
  )

  const ivB64 = btoa(String.fromCharCode(...iv))
  const ctB64 = btoa(String.fromCharCode(...new Uint8Array(cipherBuffer)))
  return `${ivB64}:${ctB64}`
}

/**
 * Descifra un payload "base64(iv):base64(ciphertext)" y retorna el objeto JSON.
 */
export async function descifrar<T>(payload: string, pin: string, salBase64: string): Promise<T> {
  const [ivB64, ctB64] = payload.split(':')
  const sal = Uint8Array.from(atob(salBase64), c => c.charCodeAt(0))
  const clave = await derivarClave(pin, sal)
  const iv = Uint8Array.from(atob(ivB64), c => c.charCodeAt(0))
  const ct = Uint8Array.from(atob(ctB64), c => c.charCodeAt(0))

  const plainBuffer = await crypto.subtle.decrypt(
    { name: ALGORITHM, iv: toBuffer(iv) },
    clave,
    toBuffer(ct)
  )
  const dec = new TextDecoder()
  return JSON.parse(dec.decode(plainBuffer)) as T
}
