// =====================================================
// SOLUCIONES COLINA — Servicio de Autenticación Local
// PIN de 6 dígitos + hash SHA-256 con sal única
// Sin servidores externos. 100% offline.
// =====================================================
import { hashPin, generarSal } from './encryptionService'
import {
  guardarPin, obtenerPinHash, obtenerPinSal,
  iniciarSesion, cerrarSesion, sesionActiva,
  esPrimeraVez, marcarInstalado,
  guardarPerfil, type PerfilEmpresa
} from './localStorageService'

export type AuthEstado = 'cargando' | 'primera-vez' | 'login' | 'autenticado'

export interface RegistroData {
  nombre: string
  nit: string
  dv: string
  correo: string
  pin: string
  telefono?: string
  direccion?: string
  ciudad?: string
}

/**
 * Determina el estado de autenticación actual.
 */
export async function obtenerEstadoAuth(): Promise<AuthEstado> {
  const primeraVez = await esPrimeraVez()
  if (primeraVez) return 'primera-vez'
  const activa = await sesionActiva()
  if (activa) return 'autenticado'
  return 'login'
}

/**
 * Registra un nuevo usuario:
 * 1. Genera sal aleatoria
 * 2. Hashea el PIN con la sal
 * 3. Guarda perfil cifrado
 * 4. Inicia sesión automáticamente
 * Retorna la sal (se necesita para descifrar datos después)
 */
export async function registrarUsuario(datos: RegistroData): Promise<string> {
  const sal = generarSal()
  const pinHasheado = await hashPin(datos.pin, sal)
  await guardarPin(pinHasheado, sal)

  const perfil: PerfilEmpresa = {
    id: crypto.randomUUID(),
    nombre: datos.nombre,
    nit: datos.nit,
    dv: datos.dv,
    correo: datos.correo,
    telefono: datos.telefono,
    direccion: datos.direccion,
    ciudad: datos.ciudad,
    creadoEn: new Date().toISOString(),
  }

  await guardarPerfil(perfil, datos.pin, sal)
  await marcarInstalado()
  await iniciarSesion(pinHasheado)
  return sal
}

/**
 * Verifica el PIN ingresado.
 * Retorna la sal si el PIN es correcto, null si no.
 */
export async function verificarPin(pinIngresado: string): Promise<string | null> {
  const pinHashGuardado = await obtenerPinHash()
  const sal = await obtenerPinSal()
  if (!pinHashGuardado || !sal) return null

  const hashIngresado = await hashPin(pinIngresado, sal)
  if (hashIngresado !== pinHashGuardado) return null

  await iniciarSesion(pinHashGuardado)
  return sal
}

/**
 * Cierra la sesión del usuario.
 */
export async function salir(): Promise<void> {
  await cerrarSesion()
}

/**
 * Verifica si hay sesión activa.
 */
export { sesionActiva }
