import React, { useState, useMemo } from 'react'
import { Search, Filter, Plus, FileText } from 'lucide-react'
import type { FacturaDetalle, NegocioInfo, ResumenPeriodo } from '../types'
import { MiniReceiptCard } from '../components/MiniReceiptCard'

interface FacturasListProps {
  negocio: NegocioInfo
  resumen: ResumenPeriodo
  facturas: FacturaDetalle[]
  onSeleccionarFactura: (factura: FacturaDetalle) => void
  onRegistrarFactura?: () => void
  onVerPerfil?: () => void
}

type FiltroEstado = 'todas' | 'aceptada' | 'enviada' | 'rechazada'

export const FacturasList: React.FC<FacturasListProps> = ({
  facturas,
  onSeleccionarFactura,
  onRegistrarFactura
}) => {
  const [busqueda, setBusqueda] = useState('')
  const [filtro, setFiltro] = useState<FiltroEstado>('todas')

  const facturasFiltradas = useMemo(() => {
    return facturas.filter(f => {
      // Filtro de estado
      if (filtro === 'aceptada' && f.estado !== 'aceptada') return false
      if (filtro === 'enviada' && (f.estado !== 'enviada' && f.estado !== 'firmada' && f.estado !== 'borrador')) return false
      if (filtro === 'rechazada' && f.estado !== 'rechazada') return false

      // Búsqueda de texto
      if (busqueda.trim()) {
        const q = busqueda.toLowerCase().trim()
        return (
          f.numeroFactura.toLowerCase().includes(q) ||
          f.clienteNombre.toLowerCase().includes(q) ||
          f.clienteNIT.toLowerCase().includes(q)
        )
      }
      return true
    })
  }, [facturas, filtro, busqueda])

  return (
    <div className="dashboard-v2-root animate-fade-in">
      {/* Encabezado v2 */}
      <header className="dashboard-v2-header">
        <div className="dashboard-saludo-box">
          <span className="saludo-tiempo">DOCUMENTOS EMITIDOS</span>
          <h1 className="saludo-titular font-serif">Mis Facturas</h1>
        </div>

        {onRegistrarFactura && (
          <button
            type="button"
            className="header-icon-circle-btn"
            onClick={onRegistrarFactura}
            aria-label="Nueva Factura"
            title="Nueva Factura"
          >
            <Plus size={20} />
          </button>
        )}
      </header>

      {/* Barra de búsqueda con icono */}
      <div className="search-bar-v2">
        <Search size={18} className="search-icon-v2" />
        <input
          type="text"
          placeholder="Buscar por número, cliente o NIT..."
          value={busqueda}
          onChange={e => setBusqueda(e.target.value)}
          className="search-input-v2 font-sans"
        />
        {busqueda && (
          <button
            type="button"
            className="search-clear-btn"
            onClick={() => setBusqueda('')}
          >
            ✕
          </button>
        )}
      </div>

      {/* Chips de filtro */}
      <div className="filtros-chips-row">
        <button
          type="button"
          className={`chip-filtro ${filtro === 'todas' ? 'activo' : ''}`}
          onClick={() => setFiltro('todas')}
        >
          Todas ({facturas.length})
        </button>
        <button
          type="button"
          className={`chip-filtro ${filtro === 'aceptada' ? 'activo' : ''}`}
          onClick={() => setFiltro('aceptada')}
        >
          Aceptadas
        </button>
        <button
          type="button"
          className={`chip-filtro ${filtro === 'enviada' ? 'activo' : ''}`}
          onClick={() => setFiltro('enviada')}
        >
          En revisión
        </button>
        <button
          type="button"
          className={`chip-filtro ${filtro === 'rechazada' ? 'activo' : ''}`}
          onClick={() => setFiltro('rechazada')}
        >
          Rechazadas
        </button>
      </div>

      {/* Lista de mini-recibos con borde dentado */}
      <div className="recientes-list" style={{ marginTop: '0.5rem' }}>
        {facturasFiltradas.length > 0 ? (
          facturasFiltradas.map(f => (
            <MiniReceiptCard
              key={f.id}
              factura={f}
              onClick={() => onSeleccionarFactura(f)}
            />
          ))
        ) : (
          <div className="estado-vacio-recibo">
            <div className="vacio-recibo-card">
              <FileText size={36} style={{ color: 'var(--color-marca)', margin: '0 auto' }} />
              <p className="vacio-recibo-texto font-serif">
                {facturas.length === 0
                  ? 'Aún no tienes facturas registradas'
                  : 'No se encontraron facturas con los filtros seleccionados'}
              </p>
              <div className="vacio-recibo-linea" />
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
export default FacturasList
