// =====================================================
// COLINA STUDIO — Cara 1: Vista Recibo de Papel Arrugado
// Fiel a la Pantalla 7 del lienzo "Gen Factura DIAN"
// =====================================================
import React, { useState } from 'react'
import { ArrowLeft, Share2, FileText, Download, Check, ShieldAlert } from 'lucide-react'
import type { FacturaDetalle } from '../types'
import { ReceiptTeeth } from './ReceiptTeeth'
import { ReceiptBarcode } from './ReceiptBarcode'
import { formatearFechaBogotaCorta } from '../utils/fechasBogota'
import { assetUrl } from '../utils/assets'

interface ReceiptViewProps {
  factura: FacturaDetalle
  texturaPapel?: boolean
  onVolver: () => void
}

export const ReceiptView: React.FC<ReceiptViewProps> = ({
  factura,
  texturaPapel = true,
  onVolver
}) => {
  const [vista, setVista] = useState<'recibo' | 'carta'>('recibo')
  const [copiado, setCopiado] = useState(false)

  const formatCOP = (val: number) =>
    val.toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 })

  const copiarCUFE = () => {
    if (factura.cufe) {
      navigator.clipboard.writeText(factura.cufe)
      setCopiado(true)
      setTimeout(() => setCopiado(false), 2000)
    }
  }

  // Generar URL para QR DIAN (o catálogo oficial)
  const qrDIANUrl = factura.cufe
    ? `https://catalogo-vpfe.dian.gov.co/document/searchqr?documentkey=${factura.cufe}`
    : `https://facturaelectronica.dian.gov.co/validador/${factura.numeroFactura}`

  const qrImageSrc = `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(qrDIANUrl)}&margin=4`

  // Compartir por WhatsApp
  const compartirWhatsApp = () => {
    const texto = `Factura Electrónica ${factura.numeroFactura}%0AEmisor: ${factura.emisorNombre}%0ACliente: ${factura.clienteNombre}%0ATotal: ${formatCOP(factura.total)}%0AConsulta tu factura en Colina Studio.`
    window.open(`https://api.whatsapp.com/send?text=${texto}`, '_blank')
  }

  // Descarga simulada de XML
  const descargarXML = () => {
    const xmlMock = `<?xml version="1.0" encoding="UTF-8"?>
<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2">
  <cbc:UBLVersionID>UBL 2.1</cbc:UBLVersionID>
  <cbc:CustomizationID>10</cbc:CustomizationID>
  <cbc:ProfileID>DIAN 1.9</cbc:ProfileID>
  <cbc:ID>${factura.numeroFactura}</cbc:ID>
  <cbc:UUID schemeName="CUFE-SHA384">${factura.cufe || 'CUFE_PENDIENTE_VALIDACION'}</cbc:UUID>
  <cbc:IssueDate>${factura.fecha.slice(0, 10)}</cbc:IssueDate>
  <cac:AccountingSupplierParty>
    <cac:Party><cac:PartyName><cbc:Name>${factura.emisorNombre}</cbc:Name></cac:PartyName></cac:Party>
  </cac:AccountingSupplierParty>
  <cac:AccountingCustomerParty>
    <cac:Party><cac:PartyName><cbc:Name>${factura.clienteNombre}</cbc:Name></cac:PartyName></cac:Party>
  </cac:AccountingCustomerParty>
  <cac:LegalMonetaryTotal>
    <cbc:PayableAmount currencyID="COP">${factura.total}</cbc:PayableAmount>
  </cac:LegalMonetaryTotal>
</Invoice>`
    const blob = new Blob([xmlMock], { type: 'application/xml' })
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = `${factura.numeroFactura}.xml`
    link.click()
  }

  // Descarga de PDF oficial carta
  const descargarPDF = () => {
    window.print()
  }

  const esAceptada = factura.estado === 'aceptada' && !!factura.fechaValidacionDIAN

  return (
    <div className="receipt-view-root">
      {/* Barra superior */}
      <header className="receipt-view-header">
        <button className="receipt-btn-icon" onClick={onVolver} aria-label="Volver">
          <ArrowLeft size={18} />
        </button>
        <h1 className="receipt-header-title font-serif">Factura {factura.numeroFactura}</h1>
        <button className="receipt-btn-icon" onClick={compartirWhatsApp} aria-label="Compartir">
          <Share2 size={18} />
        </button>
      </header>

      {/* Selector de cara: Recibo vs Carta · PDF DIAN */}
      <div className="receipt-tabs-bar">
        <button
          className={`receipt-tab-pill ${vista === 'recibo' ? 'activo' : ''}`}
          onClick={() => setVista('recibo')}
        >
          Recibo
        </button>
        <button
          className={`receipt-tab-pill ${vista === 'carta' ? 'activo' : ''}`}
          onClick={() => setVista('carta')}
        >
          Carta · PDF DIAN
        </button>
      </div>

      {/* CONTENIDO PRINCIPAL */}
      {vista === 'recibo' ? (
        <div className="receipt-wrapper animate-slide-down">
          {/* El papel del recibo */}
          <div className={`receipt-paper ${texturaPapel ? 'con-textura' : 'sin-textura'}`}>
            {/* Logo oficial del Negocio / Colina */}
            <div className="receipt-store-icon">
              <img src={assetUrl('logo.png')} alt="Logo" style={{ width: 34, height: 34, objectFit: 'contain' }} />
            </div>

            {/* Datos del Negocio Emisor */}
            <div className="receipt-emisor-block">
              <h2 className="receipt-emisor-name font-mono">{factura.emisorNombre}</h2>
              <p className="receipt-emisor-sub font-mono">
                NIT {factura.emisorNIT} {factura.emisorRegimen ? `· ${factura.emisorRegimen}` : '· Régimen Común'}
              </p>
              <p className="receipt-emisor-sub font-mono">
                {factura.emisorDireccion || 'Cra 43A # 1-50'} · {factura.emisorCiudad || 'Bogotá, Colombia'}
              </p>
            </div>

            <div className="receipt-dotted-separator" />

            {/* Título documento y consecutivo */}
            <div className="receipt-doc-block">
              <span className="receipt-doc-title font-mono">FACTURA ELECTRÓNICA DE VENTA</span>
              <div className="receipt-num-box">
                <span className="receipt-num font-mono">{factura.numeroFactura}</span>
              </div>
              <p className="receipt-meta-line font-mono">
                Fecha: {formatearFechaBogotaCorta(factura.fecha)} (Bogotá)
              </p>
              <p className="receipt-meta-line font-mono">
                Pago: {factura.formaPago || 'Contado · Transferencia'}
              </p>
            </div>

            <div className="receipt-dotted-separator" />

            {/* Adquirente / Cliente */}
            <div className="receipt-adquirente-block">
              <span className="receipt-section-tag font-mono">ADQUIRENTE</span>
              <p className="receipt-cliente-name font-mono">{factura.clienteNombre}</p>
              <p className="receipt-cliente-nit font-mono">NIT/CC {factura.clienteNIT}</p>
            </div>

            <div className="receipt-dotted-separator" />

            {/* Tabla de Ítems */}
            <div className="receipt-items-block font-mono">
              <div className="receipt-items-head">
                <span className="col-desc">DESCRIPCIÓN</span>
                <span className="col-cant">CANT</span>
                <span className="col-total">TOTAL</span>
              </div>
              <div className="receipt-items-body">
                {factura.items && factura.items.length > 0 ? (
                  factura.items.map((item, idx) => (
                    <div key={idx} className="receipt-item-row">
                      <span className="col-desc">{item.descripcion}</span>
                      <span className="col-cant">{item.cantidad}</span>
                      <span className="col-total">{formatCOP(item.total)}</span>
                    </div>
                  ))
                ) : (
                  <div className="receipt-item-row">
                    <span className="col-desc">Servicio de facturación electrónica</span>
                    <span className="col-cant">1</span>
                    <span className="col-total">{formatCOP(factura.subtotal)}</span>
                  </div>
                )}
              </div>
            </div>

            <div className="receipt-dotted-separator" />

            {/* Totales */}
            <div className="receipt-totales-block font-mono">
              <div className="receipt-total-row">
                <span>Subtotal</span>
                <span>{formatCOP(factura.subtotal)}</span>
              </div>
              <div className="receipt-total-row">
                <span>IVA 19%</span>
                <span>{formatCOP(factura.iva)}</span>
              </div>
              <div className="receipt-total-row total-destacado">
                <span>TOTAL</span>
                <span className="total-monto">{formatCOP(factura.total)}</span>
              </div>
            </div>

            {/* Sello oficial rotado (Aceptada vs Sin validar) */}
            <div className="receipt-sello-wrapper">
              {esAceptada ? (
                <div className="sello-dian sello-aceptada">
                  ACEPTADA DIAN
                </div>
              ) : (
                <div className="sello-dian sello-sin-validar">
                  SIN VALIDAR
                </div>
              )}
            </div>

            {/* Código QR DIAN + CUFE */}
            <div className="receipt-qr-cufe-block">
              <div className="receipt-qr-box">
                <img
                  src={qrImageSrc}
                  alt={`QR DIAN ${factura.numeroFactura}`}
                  className="receipt-qr-img"
                  loading="lazy"
                />
              </div>
              <div className="receipt-cufe-details font-mono">
                <span className="cufe-label">CUFE</span>
                <p className="cufe-text" onClick={copiarCUFE} title="Toca para copiar CUFE">
                  {factura.cufe
                    ? `${factura.cufe.slice(0, 36)}...`
                    : '[CUFE pendiente de validación DIAN]'}
                </p>
                {copiado && <span className="cufe-copiado-hint">✓ Copiado</span>}
                <p className="cufe-validacion">
                  {factura.fechaValidacionDIAN
                    ? `Validada por la DIAN el ${formatearFechaBogotaCorta(factura.fechaValidacionDIAN)}`
                    : 'Factura registrada en la app local'}
                </p>
              </div>
            </div>

            {/* Texto de resolución legal DIAN */}
            <div className="receipt-legal-block font-mono">
              <p>
                {factura.resolucionDIAN ||
                  'Resolución DIAN 18764000001 de 2026-01-01 · Prefijo FE · Rango 1 al 10000 · Vigencia 12 meses.'}
              </p>
              <p className="receipt-software-tag">
                Representación gráfica de la factura electrónica. Generada con el software de Colina Studio.
              </p>
            </div>

            {/* Línea punteada de corte antes del código de barras */}
            <div className="receipt-cut-line font-mono">
              <span className="cut-line-dashes">- - - - - - - - - - - - - - - - - - - - - - - - -</span>
            </div>

            {/* Código de barras */}
            <ReceiptBarcode valor={factura.numeroFactura} />

            {/* Dientes de corte al final del recibo */}
            <ReceiptTeeth color="#f7f4ec" fondo="#f5efe3" />
          </div>
        </div>
      ) : (
        /* VISTA CARTA · PDF DIAN OFICIAL */
        <div className="pdf-carta-container animate-fade-in">
          <div className="pdf-carta-sheet">
            <div className="pdf-carta-header">
              <div>
                <h2 className="pdf-empresa font-serif">{factura.emisorNombre}</h2>
                <p className="pdf-sub">NIT: {factura.emisorNIT}</p>
                <p className="pdf-sub">{factura.emisorDireccion || 'Cra 43A # 1-50, Bogotá'}</p>
                <p className="pdf-sub">Software: Colina Studio · Colombia</p>
              </div>
              <div className="pdf-factura-badge">
                <span className="pdf-tipo">FACTURA ELECTRÓNICA DE VENTA</span>
                <span className="pdf-numero font-mono">{factura.numeroFactura}</span>
                <span className="pdf-fecha">Fecha: {formatearFechaBogotaCorta(factura.fecha)}</span>
              </div>
            </div>

            <div className="pdf-cliente-box">
              <div className="pdf-col">
                <span className="pdf-label">ADQUIRENTE</span>
                <strong className="pdf-val">{factura.clienteNombre}</strong>
                <span className="pdf-val">NIT/CC: {factura.clienteNIT}</span>
              </div>
              <div className="pdf-col">
                <span className="pdf-label">FORMA DE PAGO</span>
                <span className="pdf-val">{factura.formaPago}</span>
                <span className="pdf-val">{factura.resolucionDIAN}</span>
              </div>
            </div>

            <table className="pdf-tabla-items">
              <thead>
                <tr>
                  <th>Descripción</th>
                  <th style={{ textAlign: 'center' }}>Cant.</th>
                  <th style={{ textAlign: 'right' }}>Precio Unit.</th>
                  <th style={{ textAlign: 'right' }}>Total</th>
                </tr>
              </thead>
              <tbody>
                {factura.items && factura.items.length > 0 ? (
                  factura.items.map((it, i) => (
                    <tr key={i}>
                      <td>{it.descripcion}</td>
                      <td style={{ textAlign: 'center' }}>{it.cantidad}</td>
                      <td style={{ textAlign: 'right' }}>{formatCOP(it.precioUnitario)}</td>
                      <td style={{ textAlign: 'right' }}>{formatCOP(it.total)}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td>Servicio de facturación electrónica DIAN</td>
                    <td style={{ textAlign: 'center' }}>1</td>
                    <td style={{ textAlign: 'right' }}>{formatCOP(factura.subtotal)}</td>
                    <td style={{ textAlign: 'right' }}>{formatCOP(factura.subtotal)}</td>
                  </tr>
                )}
              </tbody>
            </table>

            <div className="pdf-totales-section">
              <div className="pdf-totales-box">
                <div className="pdf-total-line">
                  <span>Subtotal:</span>
                  <span>{formatCOP(factura.subtotal)}</span>
                </div>
                <div className="pdf-total-line">
                  <span>IVA 19%:</span>
                  <span>{formatCOP(factura.iva)}</span>
                </div>
                <div className="pdf-total-line pdf-gran-total">
                  <span>TOTAL FACTURA:</span>
                  <span>{formatCOP(factura.total)}</span>
                </div>
              </div>
            </div>

            <div className="pdf-pie-legal">
              <img src={qrImageSrc} alt="QR DIAN" className="pdf-qr-img" />
              <div className="pdf-pie-texto">
                <p className="pdf-cufe font-mono">CUFE: {factura.cufe || 'Pendiente de emisión DIAN'}</p>
                <p className="pdf-anexo">
                  Documento equivalente según Anexo Técnico 1.9 DIAN. Desarrollado por Colina Studio.
                </p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Botones de acción oficial */}
      <section className="receipt-actions-section">
        <h3 className="actions-section-title font-serif">Archivos de esta factura</h3>
        <div className="actions-grid">
          <button className="btn-archivo-accion" onClick={descargarPDF}>
            <FileText size={16} />
            <span>Descargar PDF Carta</span>
          </button>
          <button className="btn-archivo-accion" onClick={descargarXML}>
            <Download size={16} />
            <span>Descargar XML UBL 2.1</span>
          </button>
          <button className="btn-archivo-accion" onClick={compartirWhatsApp}>
            <Share2 size={16} />
            <span>Compartir WhatsApp</span>
          </button>
        </div>
      </section>
    </div>
  )
}
