import { Preferences } from '@capacitor/preferences'
import type { ConfiguracionCuenta, ResolucionDIAN, ClienteFrecuente, ProductoServicio } from '../types'
import { CONFIG_DEFAULT } from '../types'

const KEYS = {
  CONFIG: 'sc_config_cuenta',
  RESOLUCIONES: 'sc_resoluciones',
  CLIENTES: 'sc_clientes_frecuentes',
  PRODUCTOS: 'sc_productos_servicios'
}

export async function cargarConfiguracion(): Promise<ConfiguracionCuenta> {
  try {
    const { value } = await Preferences.get({ key: KEYS.CONFIG })
    if (value) {
      return { ...CONFIG_DEFAULT, ...JSON.parse(value) }
    }
  } catch (err) {
    console.warn('[Colina Studio] Error al cargar configuración:', err)
  }
  return CONFIG_DEFAULT
}

export async function guardarConfiguracion(config: ConfiguracionCuenta): Promise<void> {
  await Preferences.set({ key: KEYS.CONFIG, value: JSON.stringify(config) })
}

// ── Resoluciones DIAN ──────────────────────────────────
export const RESOLUCION_DEMO: ResolucionDIAN = {
  id: 'res-default',
  numeroResolucion: '18764000001',
  prefijo: 'FE',
  rangoDesde: 1,
  rangoHasta: 10000,
  ultimoConsecutivo: 5,
  fechaInicio: '2026-01-01',
  fechaFin: '2027-01-01',
  vigenciaMeses: 12
}

export async function cargarResoluciones(): Promise<ResolucionDIAN[]> {
  try {
    const { value } = await Preferences.get({ key: KEYS.RESOLUCIONES })
    if (value) return JSON.parse(value)
  } catch (err) {
    console.warn('[Colina Studio] Error al cargar resoluciones:', err)
  }
  return [RESOLUCION_DEMO]
}

export async function guardarResoluciones(lista: ResolucionDIAN[]): Promise<void> {
  await Preferences.set({ key: KEYS.RESOLUCIONES, value: JSON.stringify(lista) })
}

/**
 * Incrementa atómicamente el consecutivo de la resolución seleccionada
 * y devuelve el número asignado (ej. FE-0006).
 */
export async function asignarSiguienteConsecutivo(resolucionId: string): Promise<string> {
  const lista = await cargarResoluciones()
  const idx = lista.findIndex(r => r.id === resolucionId)
  if (idx === -1) {
    const nuevo = RESOLUCION_DEMO.ultimoConsecutivo + 1
    return `FE-${nuevo.toString().padStart(4, '0')}`
  }

  const res = lista[idx]
  if (res.ultimoConsecutivo >= res.rangoHasta) {
    throw new Error(`El rango de facturación de la resolución ${res.numeroResolucion} se ha agotado.`)
  }

  res.ultimoConsecutivo += 1
  lista[idx] = res
  await guardarResoluciones(lista)

  return `${res.prefijo}-${res.ultimoConsecutivo.toString().padStart(4, '0')}`
}

