// =====================================================
// COLINA STUDIO — Pantalla 6: Inicio v2
// Vista principal con Hero Card, acciones y recientes
// =====================================================
import React from 'react'
import { Bell } from 'lucide-react'
import type { FacturaDetalle, NegocioInfo, ResumenPeriodo, ConfiguracionCuenta } from '../types'
import { HeroCard } from '../components/HeroCard'
import { QuickActions } from '../components/QuickActions'
import { MiniReceiptCard } from '../components/MiniReceiptCard'
import { assetUrl } from '../utils/assets'

interface DashboardV2Props {
  negocio: NegocioInfo
  resumen: ResumenPeriodo
  config: ConfiguracionCuenta
  facturas: FacturaDetalle[]
  onSeleccionarFactura: (factura: FacturaDetalle) => void
  onVerTodas: () => void
  onNuevaFactura: () => void
  onImportarXml: () => void
  onEscanearQr: () => void
  onContador: () => void
  onAbrirMenu: () => void
}

export const DashboardV2: React.FC<DashboardV2Props> = ({
  negocio,
  resumen,
  config,
  facturas,
  onSeleccionarFactura,
  onVerTodas,
  onNuevaFactura,
  onImportarXml,
  onEscanearQr,
  onContador,
  onAbrirMenu
}) => {
  // Saludo según hora del día
  const obtenerSaludo = () => {
    const hora = new Date().getHours()
    if (hora < 12) return 'Buenos días'
    if (hora < 18) return 'Buenas tardes'
    return 'Buenas noches'
  }

  const titular = config.titularNombre || negocio.nombre || 'Administrador'
  const inicial = (titular || 'N').charAt(0).toUpperCase()
  const recientes = facturas.slice(0, 4)

  return (
    <div className="dashboard-v2-root animate-fade-in">
      {/* Encabezado superior */}
      <header className="dashboard-v2-header">
        <div className="dashboard-saludo-box">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.45rem' }}>
            <img src={assetUrl('logo.png')} alt="Colina" style={{ width: 18, height: 18, objectFit: 'contain' }} />
            <span className="saludo-tiempo">{obtenerSaludo()}</span>
          </div>
          <h1 className="saludo-titular font-serif">{titular}</h1>
        </div>

        <div className="dashboard-header-actions">
          <button className="header-icon-circle-btn" aria-label="Notificaciones">
            <Bell size={18} />
          </button>
          <button
            className="header-avatar-circle"
            onClick={onAbrirMenu}
            aria-label="Abrir perfil y menú"
            title="Abrir menú"
          >
            {inicial}
          </button>
        </div>
      </header>

      {/* Grid superior de indicadores y acciones */}
      <div className="dashboard-top-grid">
        <HeroCard resumen={resumen} ambiente={config.ambienteDIAN} />
        <QuickActions
          onNueva={onNuevaFactura}
          onImportarXml={onImportarXml}
          onEscanearQr={onEscanearQr}
          onContador={onContador}
        />
      </div>

      {/* Sección Recientes */}
      <section className="dashboard-recientes-section">
        <div className="recientes-head">
          <h2 className="recientes-titulo font-serif">Recientes</h2>
          {facturas.length > 0 && (
            <button className="btn-ver-todas" onClick={onVerTodas}>
              Ver todas
            </button>
          )}
        </div>

        <div className="recientes-list">
          {recientes.length > 0 ? (
            recientes.map(f => (
              <MiniReceiptCard
                key={f.id}
                factura={f}
                onClick={() => onSeleccionarFactura(f)}
              />
            ))
          ) : (
            <div className="estado-vacio-recibo">
              <div className="vacio-recibo-card">
                <p className="vacio-recibo-linea font-mono">- - - - - - - - - - - - - - -</p>
                <p className="vacio-recibo-texto font-mono">
                  Aún no hay facturas registradas.<br />
                  Crea tu primera factura tocando el botón +
                </p>
                <p className="vacio-recibo-linea font-mono">- - - - - - - - - - - - - - -</p>
              </div>
            </div>
          )}
        </div>
      </section>
    </div>
  )
}
