// =====================================================
// COLINA STUDIO — Escáner Seguro de QR DIAN (Fase E)
// Con lista blanca de dominios oficiales DIAN
// =====================================================
import React, { useState } from 'react'
import { ArrowLeft, ScanLine, ShieldCheck, AlertCircle, CheckCircle2 } from 'lucide-react'
import type { FacturaDetalle } from '../types'
import { agregarFactura } from '../services/localStorageService'
import { hoyBogota, ahoraBogotaISO } from '../utils/fechasBogota'

interface EscanearQrModalProps {
  pin: string
  sal: string
  negocioNombre: string
  negocioNit: string
  onFacturaRegistrada: () => void
  onVolver: () => void
}

const DOMINIOS_DIAN_PERMITIDOS = [
  'catalogo-vpfe.dian.gov.co',
  'facturaelectronica.dian.gov.co',
  'dian.gov.co'
]

export const EscanearQrModal: React.FC<EscanearQrModalProps> = ({
  pin,
  sal,
  negocioNombre,
  negocioNit,
  onFacturaRegistrada,
  onVolver
}) => {
  const [textoQR, setTextoQR] = useState('')
  const [error, setError] = useState('')
  const [facturaDetectada, setFacturaDetectada] = useState<FacturaDetalle | null>(null)
  const [cargando, setCargando] = useState(false)

  const validarYProcesarQR = (contenido: string) => {
    setError('')
    const texto = contenido.trim()
    if (!texto) {
      setError('Por favor ingresa o pega el contenido del código QR.')
      return
    }

    // Caso 1: URL de validación DIAN
    if (texto.startsWith('http://') || texto.startsWith('https://')) {
      try {
        const urlObj = new URL(texto)
        const host = urlObj.hostname.toLowerCase()
        const esValido = DOMINIOS_DIAN_PERMITIDOS.some(d => host === d || host.endsWith(`.${d}`))

        if (!esValido) {
          setError(`Seguridad: El enlace del QR (${host}) no pertenece a un dominio oficial de la DIAN.`)
          return
        }

        const cufeParam = urlObj.searchParams.get('documentkey') || urlObj.pathname.split('/').pop() || ''
        const fac: FacturaDetalle = {
          id: crypto.randomUUID(),
          numeroFactura: `FE-QR-${Date.now().toString().slice(-4)}`,
          fecha: ahoraBogotaISO(),
          clienteNombre: 'Cliente (Validado por QR DIAN)',
          clienteNIT: '900000000',
          emisorNombre: negocioNombre,
          emisorNIT: negocioNit,
          resolucionDIAN: 'Resolución DIAN Validada por QR',
          formaPago: 'Contado',
          items: [],
          subtotal: 0,
          iva: 0,
          total: 0,
          estado: 'enviada',
          cufe: cufeParam || undefined,
          tieneQR: true,
          qrUrl: texto
        }
        setFacturaDetectada(fac)
        return
      } catch {
        setError('El enlace del código QR no tiene un formato URL válido.')
        return
      }
    }

    // Caso 2: Cadena estructurada DIAN (NumFac, FecFac, NitFac, ValFac, CUFE, etc.)
    const campos: Record<string, string> = {}
    const lineas = texto.split(/\r?\n|;/)
    for (const linea of lineas) {
      const pos = linea.indexOf(':')
      if (pos > 0) {
        const clave = linea.slice(0, pos).trim()
        const valor = linea.slice(pos + 1).trim()
        campos[clave] = valor
      }
    }

    const numFac = campos['NumFac'] || `FE-QR-${Date.now().toString().slice(-4)}`
    const fecFac = campos['FecFac'] || hoyBogota()
    const nitAdq = campos['DocAdq'] || '900000000'
    const valFac = parseFloat(campos['ValFac'] || '0')
    const valIva = parseFloat(campos['ValIva'] || '0')
    const valTotal = parseFloat(campos['ValFacIm'] || (valFac + valIva).toString())
    const cufe = campos['CUFE'] || ''

    const fac: FacturaDetalle = {
      id: crypto.randomUUID(),
      numeroFactura: numFac,
      fecha: `${fecFac}T12:00:00-05:00`,
      clienteNombre: `Cliente NIT ${nitAdq}`,
      clienteNIT: nitAdq,
      emisorNombre: negocioNombre,
      emisorNIT: negocioNit,
      resolucionDIAN: 'Resolución DIAN Anexo 1.9',
      formaPago: 'Contado',
      items: [],
      subtotal: valFac,
      iva: valIva,
      total: valTotal,
      estado: cufe ? 'aceptada' : 'enviada',
      cufe: cufe || undefined,
      tieneQR: true
    }
    setFacturaDetectada(fac)
  }

  const confirmarGuardar = async () => {
    if (!facturaDetectada) return
    setCargando(true)
    try {
      await agregarFactura(facturaDetectada, pin, sal)
      onFacturaRegistrada()
    } catch {
      setError('No se pudo guardar la factura escaneada.')
    } finally {
      setCargando(false)
    }
  }

  return (
    <div className="modal-screen-root animate-fade-in">
      <header className="modal-screen-header">
        <button className="menu-btn-icon" onClick={onVolver} aria-label="Volver">
          <ArrowLeft size={18} />
        </button>
        <h1 className="modal-header-title font-serif">Escanear QR DIAN</h1>
        <div style={{ width: 36 }} />
      </header>

      {error && (
        <div className="auth-error" style={{ margin: '1rem 1.5rem 0' }}>
          <AlertCircle size={16} /> {error}
        </div>
      )}

      {!facturaDetectada ? (
        <div className="escanear-qr-box">
          <div className="qr-reticle-container">
            <div className="qr-reticle-corner top-left" />
            <div className="qr-reticle-corner top-right" />
            <div className="qr-reticle-corner bottom-left" />
            <div className="qr-reticle-corner bottom-right" />
            <ScanLine size={48} className="qr-scan-pulse-icon" />
          </div>

          <h2 className="importar-title font-serif">Lectura de Código QR</h2>
          <p className="importar-desc">
            Pega el contenido o enlace del código QR de la factura electrónica DIAN para importar sus datos al instante.
          </p>

          <div className="campo-grupo" style={{ width: '100%', maxWidth: 360 }}>
            <textarea
              className="campo-input"
              rows={3}
              placeholder="Pega aquí el enlace o texto del QR DIAN..."
              value={textoQR}
              onChange={e => setTextoQR(e.target.value)}
            />
            <button
              className="btn-auth-primario"
              style={{ marginTop: '0.75rem' }}
              onClick={() => validarYProcesarQR(textoQR)}
            >
              Procesar QR
            </button>
          </div>

          <div className="qr-seguridad-aviso font-sans">
            <ShieldCheck size={16} />
            <span>Lista blanca: solo se aceptan dominios oficiales de la DIAN</span>
          </div>
        </div>
      ) : (
        <div className="importar-preview-box animate-slide-down">
          <div className="preview-status-pill">
            <CheckCircle2 size={16} />
            <span>Datos del QR leídos con éxito</span>
          </div>

          <div className="confirmacion-resumen" style={{ marginTop: '1rem' }}>
            <div className="confirmacion-row">
              <span className="confirmacion-label">Factura</span>
              <span className="confirmacion-valor font-mono">{facturaDetectada.numeroFactura}</span>
            </div>
            <div className="confirmacion-row">
              <span className="confirmacion-label">Total</span>
              <span className="confirmacion-valor">${facturaDetectada.total.toLocaleString('es-CO')}</span>
            </div>
            <div className="confirmacion-row">
              <span className="confirmacion-label">CUFE</span>
              <span className="confirmacion-valor font-mono">
                {facturaDetectada.cufe ? `${facturaDetectada.cufe.slice(0, 24)}...` : 'Sin CUFE'}
              </span>
            </div>
          </div>

          <div className="auth-btn-row" style={{ marginTop: '1.5rem' }}>
            <button className="btn-auth-secundario" onClick={() => setFacturaDetectada(null)}>
              Escanear otro
            </button>
            <button className="btn-auth-primario" onClick={confirmarGuardar} disabled={cargando}>
              {cargando ? 'Guardando...' : '✓ Guardar Factura'}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}
